WITH metrics AS (SELECT *, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY country), 4) AS credit_limit_share, SUM(credit_limit) OVER (PARTITION BY country, segment ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit, ROUND(age / SUM(age) OVER (PARTITION BY country), 4) AS age_share FROM customers), with_latest AS (SELECT s.*, x.monthly_fee FROM metrics s LEFT JOIN LATERAL (SELECT c.monthly_fee FROM subscriptions c WHERE c.customer_id = s.id ORDER BY c.end_date DESC, c.id DESC LIMIT 1) x ON TRUE), enriched AS (SELECT *, MIN(age_share) OVER (PARTITION BY country) AS country_min_age_share, ROW_NUMBER() OVER (PARTITION BY city ORDER BY cumulative_credit_limit DESC, id) AS row_seq, LEAD(age_share, 1) OVER (ORDER BY signup_date, id) AS next_age_share FROM with_latest), with_latest_customers AS (SELECT s.*, latest.order_status FROM enriched s JOIN LATERAL (SELECT c.status AS order_status FROM orders c WHERE c.customer_id = s.id ORDER BY c.shipping_fee DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, DATE_TRUNC('MONTH', signup_date) AS activity_month, ROUND(AVG(age_share), 2) AS avg_age_share, PERCENTILE_APPROX(credit_limit_share, 0.95) AS credit_limit_share_p95, PERCENTILE_APPROX(credit_limit_share, ARRAY(0.25, 0.5, 0.75)) AS credit_limit_share_quartiles FROM with_latest_customers GROUP BY ROLLUP (DATE_TRUNC('YEAR', signup_date), DATE_TRUNC('MONTH', signup_date)) HAVING avg_age_share > 0
